        return d
    d=rec(parse_newick(s))
    labels=list(d)
    pairs=[]
    for i in range(len(labels)):
        for j in range(i+1,len(labels)):
            pairs.append(d[labels[i]]+d[labels[j]])
    return pairs

for f in ['inputs/scogs_animals.zip','inputs/scogs_fungi.zip']:
